<?php
require_once __DIR__.'/../includes/functions.php';wajibLogin();$uid=(int)currentUser()['id_user'];if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$act=$_POST['aksi']??'';if($act==='all'){$s=$koneksi->prepare('UPDATE notifikasi SET dibaca=1 WHERE id_user=?');$s->bind_param('i',$uid);$s->execute();}elseif($act==='read'){$nid=(int)$_POST['id'];$s=$koneksi->prepare('UPDATE notifikasi SET dibaca=1 WHERE id_notifikasi=? AND id_user=?');$s->bind_param('ii',$nid,$uid);$s->execute();}flash('Notifikasi diperbarui.');redirect('siswa/notifikasi.php');}$s=$koneksi->prepare('SELECT * FROM notifikasi WHERE id_user=? ORDER BY created_at DESC LIMIT 100');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$pageTitle='Notifikasi';require __DIR__.'/../includes/header.php';?><div class="panel"><div class="panel-head"><div><h2>Pusat notifikasi</h2><small class="muted">Informasi status laporan dan klaim kamu.</small></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="aksi" value="all"><button class="btn secondary sm">Tandai semua dibaca</button></form></div><?php if(!$rows->num_rows):?><div class="empty">Belum ada notifikasi.</div><?php endif;while($r=$rows->fetch_assoc()):?><div class="item"><div class="item-thumb"></div><div class="item-info"><b><?=e($r['judul'])?> <?=!$r['dibaca']?'<span class="badge diproses">Baru</span>':''?></b><small><?=e($r['pesan'])?> · <?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></small></div><?php if(!$r['dibaca']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="aksi" value="read"><input type="hidden" name="id" value="<?=$r['id_notifikasi']?>"><button class="btn secondary sm">Tandai dibaca</button></form><?php endif;?></div><?php endwhile;?></div><?php require __DIR__.'/../includes/footer.php';?>
